import json

def transform_debug(grid, verbose=False):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(1 for row in grid for x in row if x == c))
    out = [[grid[r][c] for c in range(w)] for r in range(h)]

    non_bg = set(c for c in set(x for row in grid for x in row) if c != bg)

    detected = 0
    for color in non_bg:
        positions = sorted([(r, c) for r in range(h) for c in range(w) if grid[r][c] == color])
        if not positions:
            continue

        min_r = min(p[0] for p in positions)
        max_r = max(p[0] for p in positions)
        min_c = min(p[1] for p in positions)
        max_c = max(p[1] for p in positions)
        h_rect = max_r - min_r + 1
        w_rect = max_c - min_c + 1

        expected_border = set((r, c) for r in range(min_r, max_r + 1) 
                                  for c in range(min_c, max_c + 1)
                                  if r == min_r or r == max_r or c == min_c or c == max_c)

        is_hollow = set(positions) == expected_border

        if verbose:
            print(f"Color {color}: size {h_rect}x{w_rect}, holes={len(expected_border)-len(positions)}, hollow={is_hollow}")

        if is_hollow:
            detected += 1
            fill_color = 2 if h_rect == 4 else 7
            for r in range(min_r + 1, max_r):
                for c in range(min_c + 1, max_c):
                    if out[r][c] == bg:
                        out[r][c] = fill_color

            if verbose:
                print(f"  FILL: color {fill_color}")

    return out, detected

