import json

def find_connected_hollow(grid, bg_color):
    """Find all connected hollow structures in the grid"""
    h, w = len(grid), len(grid[0])

    # Find all non-bg positions for each color
    color_pos = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg_color:
                c_val = grid[r][c]
                if c_val not in color_pos:
                    color_pos[c_val] = []
                color_pos[c_val].append((r, c))

    hollows = []
    for color, positions in sorted(color_pos.items()):
        # Find connected components
        visited = set()
        for start in positions:
            if start in visited:
                continue

            # BFS to find connected component (including background cells inside)
            component = []
            queue = [start]
            while queue:
                r, c = queue.pop(0)
                if (r, c) in visited:
                    continue
                visited.add((r, c))

                # Add color cells
                component.append((r, c))
                for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        if grid[nr][nc] == color:
                            queue.append((nr, nc))

            if not component:
                continue

            # Check if this component forms a hollow square
            min_r, max_r = min(c[0] for c in component), max(c[0] for c in component)
            min_c, max_c = min(c[1] for c in component), max(c[1] for c in component)
            h_rect = max_r - min_r + 1
            w_rect = max_c - min_c + 1

            # Only consider square-ish structures (size 3,4,5)
            if not (3 <= h_rect <= 5 and 3 <= w_rect <= 5):
                continue

            # Check if hollow with this bounding box
            # The component cells should all be on the border
            expected_border = set((r, c) for r in range(min_r, max_r + 1)
                                      for c in range(min_c, max_c + 1)
                                      if r == min_r or r == max_r or c == min_c or c == max_c)

            # Component must match exactly the border
            if set(component) != expected_border:
                continue

            hollows.append({
                'color': color,
                'top': min_r, 'bottom': max_r,
                'left': min_c, 'right': max_c,
                'size': (h_rect, w_rect)
            })

    return hollows

